import logging

from src.config_loader import AgentConfig
from src.exceptions import ResourceNotFoundError

logger = logging.getLogger(__name__)


class Agent:
    def __init__(self, api_obj):
        self._obj = api_obj

    @property
    def id(self):
        return self._obj.id

    @property
    def name(self):
        return self._obj.name


def create_agent(client, config: AgentConfig, default_model: str, existing: bool = False) -> Agent:
    if existing:
        for page in client.beta.agents.list().iter_pages():
            for agent in page.data:
                if agent.name == config.name:
                    expected_model = config.model or default_model
                    actual_model = getattr(agent, "model", None)
                    if actual_model and actual_model != expected_model:
                        logger.warning(
                            "Reusing existing agent '%s' with model '%s'; config specifies '%s'.",
                            config.name, actual_model, expected_model,
                        )
                    return Agent(agent)
        raise ResourceNotFoundError(f"Existing agent '{config.name}' not found")
    model = config.model or default_model
    obj = client.beta.agents.create(
        name=config.name,
        model=model,
        system=config.system,
        tools=config.tools,
        mcp_servers=config.mcp_servers or [],
        skills=config.skills or [],
        description=config.description or None,
    )
    return Agent(obj)

import logging

from src.config_loader import EnvironmentConfig
from src.exceptions import ResourceNotFoundError

logger = logging.getLogger(__name__)


class Environment:
    def __init__(self, api_obj):
        self._obj = api_obj

    @property
    def id(self):
        return self._obj.id

    @property
    def name(self):
        return self._obj.name


def create_environment(client, config: EnvironmentConfig, existing: bool = False) -> Environment:
    if existing:
        for page in client.beta.environments.list().iter_pages():
            for env in page.data:
                if env.name == config.name:
                    logger.debug("Reusing existing environment '%s'.", config.name)
                    return Environment(env)
        raise ResourceNotFoundError(f"Existing environment '{config.name}' not found")
    api_config = {"type": "cloud", **config.config}
    obj = client.beta.environments.create(
        name=config.name,
        config=api_config,
    )
    return Environment(obj)

from typing import Optional


class Session:
    def __init__(self, api_obj):
        self._obj = api_obj

    @property
    def id(self):
        return self._obj.id


def create_session(client, agent_id: str, environment_id: str, title: Optional[str] = None) -> Session:
    kwargs = {"agent": agent_id, "environment_id": environment_id}
    if title:
        # Strip Unicode control/format characters (newlines, tabs, etc.)
        clean_title = "".join(c for c in title if c.isprintable()).strip()
        if clean_title:
            kwargs["title"] = clean_title
    obj = client.beta.sessions.create(**kwargs)
    return Session(obj)

from dataclasses import dataclass, field
from typing import Optional
import yaml


@dataclass
class GlobalConfig:
    api_key: str
    default_model: str
    environments_config: str
    agents_config: str


@dataclass
class EnvironmentConfig:
    name: str
    description: str = ""
    config: dict = field(default_factory=dict)


@dataclass
class AgentConfig:
    name: str
    system: str
    model: Optional[str] = None
    description: str = ""
    tools: list = field(default_factory=list)
    mcp_servers: list = field(default_factory=list)
    skills: list = field(default_factory=list)


def load_global_config(path: str) -> GlobalConfig:
    try:
        with open(path) as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"Global config file not found: {path}")
    except yaml.YAMLError as exc:
        raise ValueError(f"Failed to parse global config '{path}': {exc}")
    if not isinstance(data, dict):
        raise ValueError(f"Global config '{path}' must be a mapping at the top level")
    if not data.get("default_model"):
        raise ValueError("global config missing required field: default_model")
    if not data.get("environments_config"):
        raise ValueError("global config missing required field: environments_config")
    if not data.get("agents_config"):
        raise ValueError("global config missing required field: agents_config")
    return GlobalConfig(
        api_key=data.get("anthropic_api_key", ""),
        default_model=data["default_model"],
        environments_config=data["environments_config"],
        agents_config=data["agents_config"],
    )


def load_environments_config(path: str) -> list[EnvironmentConfig]:
    try:
        with open(path) as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"Environments config file not found: {path}")
    except yaml.YAMLError as exc:
        raise ValueError(f"Failed to parse environments config '{path}': {exc}")
    if not isinstance(data, dict):
        raise ValueError(
            f"Invalid environments config structure in '{path}': expected a mapping at top level"
        )
    envs = data.get("environments", [])
    result = []
    for idx, item in enumerate(envs):
        if not item.get("name"):
            raise ValueError(f"environment entry {idx} missing required field: name")
        result.append(EnvironmentConfig(
            name=item["name"],
            description=item.get("description", ""),
            config=item.get("config", {}),
        ))
    return result


def load_agents_config(path: str) -> list[AgentConfig]:
    try:
        with open(path) as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"Agents config file not found: {path}")
    except yaml.YAMLError as exc:
        raise ValueError(f"Failed to parse agents config '{path}': {exc}")
    if not isinstance(data, dict):
        raise ValueError(
            f"Invalid agents config structure in '{path}': expected a mapping at top level"
        )
    agents = data.get("agents", [])
    result = []
    for idx, item in enumerate(agents):
        if not item.get("name"):
            raise ValueError(f"agent entry {idx} missing required field: name")
        if not item.get("system"):
            raise ValueError(f"agent '{item.get('name')}' missing required field: system")
        result.append(AgentConfig(
            name=item["name"],
            model=item.get("model"),
            description=item.get("description", ""),
            system=item["system"],
            tools=item.get("tools", []),
            mcp_servers=item.get("mcp_servers", []),
            skills=item.get("skills", []),
        ))
    return result

